import json

def extract_json(text: str) -> dict | None:
    if not isinstance(text, str):
        return None

    decoder = json.JSONDecoder()
    start = text.find("{")

    while start != -1:
        try:
            obj, _ = decoder.raw_decode(text, start)
        except ValueError:
            start = text.find("{", start + 1)
            continue

        if isinstance(obj, dict):
            return obj

        start = text.find("{", start + 1)

    return None

